const D = { density: .55, scale: 1, energy: .62, speed: 1, hue: 320, x: .5, y: .5, glow: .5, style: 'tri-jewel', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const H = x => ((x % 360) + 360) % 360;
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- bake the Rauzy fractal (Tribonacci substitution + complex-eigenplane projection) into 3 per-residue mask buffers ----
const dens = Math.min(1, Math.max(0, P.density));
const BUFN = Math.min(820, Math.max(440, Math.round(Math.max(width, height) * 0.72)));
const N = Math.round(2200 + dens * 4200);            // 2200..6400 substitution points (first-poke: obvious fill change)
const edge = (P.style === 'neon-edge');
const key = [width, height, BUFN, N, P.seed, edge ? 'E' : 'F'].join('|');
if (S.key !== key) {
  S.key = key;
  if (S.bufs) { for (let b = 1; b < S.bufs.length; b++) { const g = S.bufs[b]; if (g && g.remove) g.remove(); } }
  // seed = static rotation + optional mirror of the projected fractal (reproducible orientation)
  const th0 = fr(1) * Math.PI * 2, ct = Math.cos(th0), stt = Math.sin(th0), mir = fr(2) > 0.5 ? -1 : 1;
  // phi(letter) = left-eigenvector components of the Tribonacci incidence matrix (projection onto contracting complex eigenplane)
  const PH = [null, [1, 0], [-1.4196433776070805, 0.6062907292071993], [-0.7718445063460384, -1.1151425080399375]];
  const sub = [null, [1, 2], [1, 3], [1]];
  let w = [1];
  while (w.length < N) { const nx = []; for (let q = 0; q < w.length; q++) { const s = sub[w[q]]; for (let r = 0; r < s.length; r++) nx.push(s[r]); } w = nx; }
  const M = Math.min(N, w.length);
  const xs = new Float32Array(M), ys = new Float32Array(M), cs = new Uint8Array(M);
  let zx = 0, zy = 0, mnx = 1e9, mxx = -1e9, mny = 1e9, mxy = -1e9;
  for (let k = 0; k < M; k++) {
    const c = w[k]; zx += PH[c][0]; zy += PH[c][1];
    const rx = zx * ct - zy * stt, ry = (zx * stt + zy * ct) * mir;
    xs[k] = rx; ys[k] = ry; cs[k] = c;
    if (rx < mnx) mnx = rx; if (rx > mxx) mxx = rx; if (ry < mny) mny = ry; if (ry > mxy) mxy = ry;
  }
  const fbw = (mxx - mnx) || 1, fbh = (mxy - mny) || 1, span = Math.max(fbw, fbh);
  const marg = 0.09, sc = BUFN * (1 - 2 * marg) / span, ccx = (mnx + mxx) / 2, ccy = (mny + mxy) / 2;
  const g1 = createGraphics(BUFN, BUFN), g2 = createGraphics(BUFN, BUFN), g3 = createGraphics(BUFN, BUFN);
  const gg = [null, g1, g2, g3];
  for (let c = 1; c <= 3; c++) { gg[c].pixelDensity(1); gg[c].noStroke(); }
  const jit = BUFN * 0.010;
  if (!edge) {
    const rDot = Math.max(2.6, BUFN * 0.0085), dA = 70 + dens * 42;
    for (let c = 1; c <= 3; c++) gg[c].fill(255, 255, 255, dA);
    for (let k = 0; k < M; k++) {
      const c = cs[k], jx = (fr(k * 2 + 7) * 2 - 1) * jit, jy = (fr(k * 2 + 8) * 2 - 1) * jit;
      gg[c].circle(BUFN / 2 + (xs[k] - ccx) * sc + jx, BUFN / 2 - (ys[k] - ccy) * sc + jy, rDot);
    }
  } else {
    // coarse occupancy so each residue class fills SOLID, then keep only boundary cells -> jagged fractal outlines
    const GN = Math.round(Math.sqrt(M / 1.6)), occ = [null, new Uint8Array(GN * GN), new Uint8Array(GN * GN), new Uint8Array(GN * GN)];
    for (let k = 0; k < M; k++) {
      const c = cs[k], gx = Math.floor((xs[k] - mnx) / fbw * (GN - 1)), gy = Math.floor((ys[k] - mny) / fbh * (GN - 1));
      occ[c][gy * GN + gx] = 1;
    }
    const rDot = Math.max(3, (BUFN / GN) * 0.85);
    for (let c = 1; c <= 3; c++) gg[c].fill(255, 255, 255, 150);
    for (let c = 1; c <= 3; c++) {
      const o = occ[c];
      for (let gy = 0; gy < GN; gy++) for (let gx = 0; gx < GN; gx++) {
        if (!o[gy * GN + gx]) continue;
        const up = gy > 0 ? o[(gy - 1) * GN + gx] : 0, dn = gy < GN - 1 ? o[(gy + 1) * GN + gx] : 0, lf = gx > 0 ? o[gy * GN + gx - 1] : 0, rt = gx < GN - 1 ? o[gy * GN + gx + 1] : 0;
        if (up && dn && lf && rt) continue;             // interior -> keep only boundary cells
        const fx = mnx + (gx + 0.5) / GN * fbw, fy = mny + (gy + 0.5) / GN * fbh;
        gg[c].circle(BUFN / 2 + (fx - ccx) * sc, BUFN / 2 - (fy - ccy) * sc, rDot);
      }
    }
  }
  S.bufs = [null, g1, g2, g3];
}

// ---- live: fill frame, then rotate + re-color the three colored copies (continuous K.t motion floor) ----
const st = P.style, en = Math.min(1, Math.max(0, P.energy)), spd = P.speed, gl = Math.min(1, Math.max(0, P.glow));
const sec = K.section | 0, intn = (K.intensity != null ? K.intensity : 0.6), al = Math.min(100, Math.max(0, P.alpha)) / 100;
const drift = K.t * 2.2 + sec * 13;                    // slow palette rotation / re-color
let cols, bg, add, aBase, tA;
if (st === 'pastel') {
  cols = [[H(P.hue + drift), 33, 99], [H(P.hue + 215 + drift), 30, 97], [H(P.hue + 85 + drift), 40, 100]];
  bg = [H(P.hue + 215), 26, 20]; add = false; aBase = 96; tA = 80;
} else if (st === 'thermal') {
  cols = [[H(18 + drift * 0.5), 90, 100], [H(46 + drift * 0.5), 92, 100], [H(214 + drift * 0.5), 82, 96]];
  bg = [232, 62, 5]; add = true; aBase = 90; tA = 78;
} else if (st === 'neon-edge') {
  cols = [[H(P.hue + drift), 92, 100], [H(P.hue + 215 + drift), 90, 100], [H(P.hue + 85 + drift), 95, 100]];
  bg = [H(P.hue + 215), 72, 6]; add = true; aBase = 100; tA = 74;
} else if (st === 'ink') {
  cols = [[40, 7, 24], [38, 7, 45], [42, 6, 64]];
  bg = [40, 13, 86]; add = false; aBase = 100; tA = 92;
} else {                                                // tri-jewel (default): magenta / teal / gold
  cols = [[H(P.hue + drift), 82, 92], [H(P.hue + 215 + drift), 80, 90], [H(P.hue + 85 + drift), 85, 90]];
  bg = [H(P.hue + 215), 52, 14]; add = false; aBase = 100; tA = 80;
}

noStroke();
fill(bg[0], bg[1], bg[2], tA * al);                    // trail-clear / frame fill
rect(0, 0, width, height);

push();
translate(P.x * width, P.y * height);
rotate(K.t * 0.024 * spd);                             // slow continuous rotation = motion floor
imageMode(CENTER);
if (add) blendMode(ADD);
const disp = u * 1.25 * P.scale;
const aa = Math.min(100, aBase * (0.72 + 0.28 * en)) * al;
for (let c = 1; c <= 3; c++) {
  const cc = cols[c - 1];
  const bri = Math.min(100, cc[2] * (1 + 0.09 * Math.sin(K.t * 0.45 + c * 2.1)));  // slow per-lobe breathing
  tint(cc[0], cc[1], bri, aa);
  image(S.bufs[c], 0, 0, disp, disp);
}
noTint();
blendMode(BLEND);
imageMode(CORNER);
pop();

// central soft bloom (partial-frame, breathes on K.t + beat; ADD alpha capped) — energy/glow
const beat = K.pulse * 0.5 + A.bass * 0.9 + K.swell * 0.3;
const glowR = u * (0.42 + 0.14 * Math.sin(K.t * 0.3)) * (0.7 + gl) * P.scale;
const gA = (5 + en * 13 + beat * 9) * (0.5 + intn * 0.7) * al;
if (gA > 0.4) {
  push(); blendMode(ADD); noStroke();
  const gh = H(cols[0][0] + 18);
  for (let i = 0; i < 3; i++) { fill(gh, 42, 100, gA * (0.42 - i * 0.12)); circle(P.x * width, P.y * height, glowR * (0.55 + i * 0.55)); }
  blendMode(BLEND); pop();
}
